    if(name==='primary-band'||name==='comparison-band'){m[name.split('-')[0]].band=Number(node.value);dirty(c);scheduleDraw(c,0);return;}
    if(name==='mode'){m.mode=node.value;dirty(c);scheduleDraw(c,0);return;}
